-- Name: marketplace_stockmovement; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketplace_stockmovement (
    id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    delta integer NOT NULL,
    resulting_quantity integer NOT NULL,
    reason character varying(20) NOT NULL,
    note text NOT NULL,
    actor_id uuid,
    listing_id uuid NOT NULL,
    CONSTRAINT marketplace_stockmovement_resulting_quantity_check CHECK ((resulting_quantity >= 0))
);


ALTER TABLE public.marketplace_stockmovement OWNER TO postgres;

--
-- Name: marketplace_vehiclelisting; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketplace_vehiclelisting (
    id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    title character varying(255) NOT NULL,
    year integer NOT NULL,
    registration_number character varying(20) NOT NULL,
    vin character varying(50) NOT NULL,
    mileage integer NOT NULL,
    fuel_type character varying(20) NOT NULL,
    transmission character varying(20) NOT NULL,
    body_type character varying(50) NOT NULL,
    price numeric(12,2) NOT NULL,
    currency character varying(10) NOT NULL,
    condition character varying(20) NOT NULL,
    description text NOT NULL,
    primary_image_url character varying(200) NOT NULL,
    images jsonb NOT NULL,
    location_city character varying(100) NOT NULL,
    location_postcode character varying(20) NOT NULL,
    status character varying(30) NOT NULL,
    submitted_at timestamp with time zone NOT NULL,
    reviewed_at timestamp with time zone,
    rejection_reason text NOT NULL,
    admin_notes text NOT NULL,
    is_active boolean NOT NULL,
    make_id uuid NOT NULL,
    model_id uuid NOT NULL,
    organisation_id uuid,
    reviewed_by_id uuid,
    seller_id uuid NOT NULL,
    variant_id uuid,
    CONSTRAINT marketplace_vehiclelisting_mileage_check CHECK ((mileage >= 0)),
    CONSTRAINT marketplace_vehiclelisting_year_check CHECK ((year >= 0))
);


ALTER TABLE public.marketplace_vehiclelisting OWNER TO postgres;

